// The user's book companion docs (2026-10-13): lib/data/book_companions.dart,
// generated by tools/book_companions/docx_to_dart.py.
//
// Holds: every book has the Bible's parts; no writers' note or emoji reached a
// reader; the stage split; the pregnancy shelf carries the doc companion (an
// existing entry keeping its id and Hindi); the parenting shelf lists the
// parenting books and opens them in the Book Companion; the companion draws
// the Take's pointers and the closing section; and it is wired.
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:parentveda/data/book_companions.dart';
import 'package:parentveda/data/read_next_data.dart';
import 'package:parentveda/models/read_item.dart';
import 'package:parentveda/screens/book_companion_screen.dart';
import 'package:parentveda/screens/post_pregnancy/pp_book_docs.dart';
import 'package:parentveda/screens/post_pregnancy/pp_reading_data.dart';

List<String> _strings(BookDoc d) => [
      d.title, d.author, d.about, d.authorIntro, d.philosophy, d.take,
      ...d.recommendedFor, ...d.themes, ...d.otherBooks, ...d.quotes,
      for (final i in d.ideas) ...[i.title, i.body, ...i.points],
      for (final c in d.chapters) ...[c.title, c.summary, ...c.points],
      for (final p in d.takePoints) p.text,
      d.addendumTitle, d.addendumBody, ...d.addendumPoints,
    ];

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  group('the docs', () {
    test('40 books, each with the Bible\'s parts', () {
      expect(kBookDocList, hasLength(40));
      for (final d in kBookDocList) {
        for (final s in [d.title, d.author, d.about, d.philosophy]) {
          expect(s.trim(), isNotEmpty, reason: d.id);
        }
        expect(d.ideas, hasLength(5), reason: '${d.id}: five ideas');
        for (final i in d.ideas) {
          expect(i.body, isNotEmpty, reason: '${d.id} ${i.title}');
          expect(i.title.length, lessThan(100), reason: '${d.id}: a title glued to its body');
        }
        expect(d.chapters.length, greaterThanOrEqualTo(4), reason: d.id);
        for (final c in d.chapters) {
          expect(c.title.length, lessThan(100), reason: '${d.id}: "${c.title}"');
        }
        expect(d.take.isNotEmpty || d.takePoints.isNotEmpty, isTrue, reason: d.id);
      }
    });

    test('no writers\' note, emoji or placeholder reached a reader', () {
      // Case-sensitive: the writers' blocks are in capitals ("BOOK ID:"), and
      // "this book identifies" must not count.
      final notes = RegExp(r'BOOK ID:|COPYRIGHT CHECK|QUALITY CHECK|LAST VERIFIED|STATUS:|future-ready|'
          r'add cover art|Read More:|Bible v\d|WORD COUNT');
      final emoji = RegExp('[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]', unicode: true);
      for (final d in kBookDocList) {
        for (final s in _strings(d)) {
          expect(notes.hasMatch(s), isFalse, reason: '${d.id}: "$s"');
          expect(emoji.hasMatch(s), isFalse, reason: '${d.id}: "$s"');
        }
      }
    });

    test('the Take keeps the doc\'s good and worth-knowing pointers', () {
      final d = kBookDocList.firstWhere((d) => d.id == 'book_bringing_up_b_b');
      expect(d.takePoints.where((p) => p.good), isNotEmpty);
      expect(d.takePoints.where((p) => !p.good), isNotEmpty);
    });
  });

  group('the shelves', () {
    test('the stage split', () {
      BookStage s(String id) => bookStage(kBookDocList.firstWhere((d) => d.id == id));
      expect(s('book_expecting_better'), BookStage.pregnancy);
      expect(s('book_the_happiest_baby_on_the_block'), BookStage.both);
      expect(s('book_no_drama_discipline'), BookStage.parenting);
    });

    test('pregnancy: an existing entry keeps its id and Hindi, and gains the doc companion', () {
      final wte = kReadItems.firstWhere((r) => r.id == 'book_what_to_expect');
      expect(wte.reason.hi, isNot(wte.reason.en), reason: 'the shelf\'s Hindi is kept');
      expect(wte.companion!.takePoints, isNotEmpty, reason: 'the doc\'s companion');
      final books = kReadItems.where((r) => r.type == ReadType.book).map((r) => r.id).toSet();
      for (final d in kBookDocList.where((d) => bookStage(d) != BookStage.parenting)) {
        expect(books, contains(bookShelfId(d)), reason: d.id);
      }
    });

    test('parenting: every parenting and newborn book is a Book Summary', () {
      final ids = {for (final a in readCatalog.where((a) => a.kind == ReadKind.bookSummary)) a.id};
      for (final d in kBookDocList.where((d) => bookStage(d) != BookStage.pregnancy)) {
        expect(ids, contains(bookShelfId(d)), reason: d.id);
      }
      expect(kPpBookArticles.every((a) => bookDocFor(a.id) != null), isTrue);
    });
  });

  testWidgets('the companion draws the doc: the Take\'s pointers and the closing section', (tester) async {
    tester.view.physicalSize = const Size(400, 9000);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);
    final d = kBookDocList.firstWhere((d) => d.id == 'book_bringing_up_b_b');
    await tester.pumpWidget(MaterialApp(home: BookCompanionScreen(item: bookReadItem(d))));
    await tester.pump();
    expect(tester.takeException(), isNull);
    expect(find.text(d.takePoints.first.text), findsOneWidget);
    expect(find.text(d.addendumTitle), findsOneWidget);
  });

  test('wired: both shelves reach the companion', () {
    String src(String p) => File(p).readAsStringSync();
    expect(src('lib/data/read_next_data.dart'), contains('bookReadItem(d, base: r)'));
    expect(src('lib/screens/read_next_screen.dart'), contains('BookCompanionScreen(item: item'));
    expect(src('lib/screens/post_pregnancy/reading_reader_screen.dart'),
        contains('return BookCompanionScreen(item: bookReadItem(d));'));
    expect(src('lib/screens/post_pregnancy/pp_reading_data.dart'), contains('...kPpBookArticles'));
  });
}
